MSTest **does not have** `Assert.IsGreaterThan` or `Assert.IsInRange` — those don't exist. Here's what to use instead:

## MSTest Options for Boundary Checks

| Need | Approach |
|------|----------|
| Value comparisons | `Assert.IsTrue(value > 50)` or use **`Assert.That.Value(x).IsGreaterThan(y)`** (MSTest 3.8+) |
| Range checks | `Assert.IsTrue(value >= 0 && value <= 100)` |
| Equality with tolerance | `Assert.AreEqual(expected, actual, delta)` |

## Recommended Test Structure

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Contoso.Scoring;

namespace Contoso.Scoring.Tests;

[TestClass]
public class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calc = new();

    [TestMethod]
    public void CalculatePercentage_PerfectScore_Returns100()
    {
        double result = _calc.CalculatePercentage(10, 10);
        Assert.AreEqual(100.0, result, 0.001);
    }

    [TestMethod]
    public void CalculatePercentage_PartialScore_ReturnsExpected()
    {
        double result = _calc.CalculatePercentage(3, 4);
        Assert.AreEqual(75.0, result, 0.001);
    }

    [TestMethod]
    public void CalculatePercentage_ResultIsInValidRange()
    {
        double result = _calc.CalculatePercentage(7, 10);
        Assert.IsTrue(result >= 0.0 && result <= 100.0,
            $"Expected 0-100 but got {result}");
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        _calc.CalculatePercentage(5, 0);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        _calc.CalculatePercentage(11, 10);
    }

    [DataTestMethod]
    [DataRow(90.0, "A")]
    [DataRow(89.99, "B")]
    [DataRow(80.0, "B")]
    [DataRow(70.0, "C")]
    [DataRow(60.0, "D")]
    [DataRow(59.99, "F")]
    public void GetGrade_BoundaryValues_ReturnsCorrectGrade(double pct, string expected)
    {
        Assert.AreEqual(expected, _calc.GetGrade(pct));
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_CapsAt100()
    {
        double result = _calc.NormalizeScore(150, 100);
        Assert.AreEqual(100.0, result, 0.001);
    }

    [TestMethod]
    public void NormalizeScore_ResultNeverExceeds100()
    {
        double result = _calc.NormalizeScore(50, 80);
        Assert.IsTrue(result >= 0.0 && result <= 100.0,
            $"Expected 0-100 but got {result}");
    }
}
```

## Key Takeaways

- **`Assert.AreEqual(expected, actual, delta)`** — use for floating-point comparisons (the `delta` overload is essential)
- **`Assert.IsTrue(condition, message)`** — your go-to for range/comparison checks
- **`Assert.ThrowsException<T>(() => ...)`** — alternative to `[ExpectedException]` for more targeted exception checks
- **`[DataTestMethod]` + `[DataRow]`** — ideal for testing boundary values systematically
